elseif($action==='resolve')$nahal->resolve($_POST['job']??'',(int)($_POST['charge']??-1));
elseif($action==='plan'){ $plans=getSubscriptionPlans();foreach($plans as &$plan)if($plan['id']===($_POST['id']??'')){foreach(['max_projects','max_members','storage_mb','nahal_projects','ehsan_projects'] as $field){$value=(int)($_POST[$field]??0);if($value<(in_array($field,['nahal_projects','ehsan_projects'],true)?0:1)||$value>1000000)throw new RuntimeException('سقف پلن معتبر نیست.');$plan[$field]=$value;}if((($plan['nahal_projects']??0)>0||($plan['ehsan_projects']??0)>0)&&!in_array('ai_connect',ProjectPlans::modules($plan),true))throw new RuntimeException('پلن دارای کارمند باید دسترسی هوش مصنوعی هم داشته باشد.');}unset($plan);saveSubscriptionPlans($plans);}
elseif($action==='adopt'){$p=getCurrentProject($_POST['pid']??'',true);if(!$p)throw new RuntimeException('پروژه یافت نشد.');$service->complimentary($p,$_POST['owner']??'',ProjectPlans::find($_POST['plan_id']??''),$_POST['cycle']??'monthly');}
elseif($action==='free_project'){ $name=trim($_POST['project_name']??'');if($name==='')throw new RuntimeException('نام پروژه لازم است.');$member=ProjectPurchases::account(['account_username'=>$_POST['username']??'','account_password'=>$_POST['password']??'','customer_mobile'=>$_POST['mobile']??'']);$pid='staff_'.bin2hex(random_bytes(12));$plan=ProjectPlans::find($_POST['plan_id']??'');$p=['id'=>$pid,'name'=>$name,'activeFrom'=>date('Y-m-d'),'activeTo'=>date('Y-m-d',strtotime('+1 month')),'users'=>[$member],'products'=>[],'settings'=>['platform_type'=>'custom','active_modules'=>ProjectPlans::modules($plan),'subscription'=>['modules'=>ProjectPlans::modules($plan)],'onboarding'=>['created_at'=>time(),'revision'=>0,'steps'=>[]]]];ProjectMembers::prepareStorage();if(!db_save_project($p))throw new RuntimeException('ساخت پروژه انجام نشد.');$service->complimentary($p,$member['username'],$plan);}
else throw new RuntimeException('عملیات معتبر نیست.');$message='تغییرات ثبت شد.';}}
catch(Throwable $e){http_response_code(422);$error=$e instanceof RuntimeException?$e->getMessage():'عملیات انجام نشد.';}
